INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D029_ABILITY_HELP','+1 Food per worked Tundra (up to +4) and +1 Science per worked Snow (up to +3) per city. +1 Culture in cities founded on Tundra or Snow.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D029_CIV_PEDIA','Thallia''s settlements survive the long cold by treating mutual dependence as a strength. Lichen symbiosis informs their horticulture and civic life.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D029_STRATEGY','Settle cold rivers where nearby hills can supply Production. Work Tundra for growth and Snow for research, and claim enough cold plots for both Garden thresholds.');
