INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D029_FALLBACK_1','We have heard your terms.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC3_D029_FIRST_GREETING_1','A lichen is neither one creature nor truly alone. Perhaps your people will understand this wisdom.');
